537	    name,
538	    lo: { x: c0.x + Math.min(a[0], b[0]), y: c0.y + local.lo.y, z: c0.z + Math.min(a[1], b[1]) },
539	    hi: { x: c0.x + Math.max(a[0], b[0]), y: c0.y + local.hi.y, z: c0.z + Math.max(a[1], b[1]) }
540	  };
541	}
542	const backing = place({ lo: BACK_LO, hi: BACK_HI }, 'backing');
543	const stand = place(STAND_LOCAL, 'stand');
544	const bracket = place(BRACKET_LOCAL, 'bracket');
545	const headCap = place(CAP_LOCAL, 'cap');
546	const SOLIDS: NamedBox[] = [backing, stand, bracket, headCap];   // NO exemption for any
547	const refSocket = new THREE.Vector3(c0.x, c0.y + FIXED_APPARATUS_SOCKET, c0.z);
548	const solidCapY = c0.y + SOLID_CAP_LOCAL_Y;
549	const headCapTopY = c0.y + HEAD_CAP_TOP_LOCAL_Y;
550	
551	const boxReport = (b: NamedBox) => ({
552	  name: b.name,
553	  lo: { x: r2(b.lo.x), y: r2(b.lo.y), z: r2(b.lo.z) },
554	  hi: { x: r2(b.hi.x), y: r2(b.hi.y), z: r2(b.hi.z) },
555	  sizeUnits: { x: r2(b.hi.x - b.lo.x), y: r2(b.hi.y - b.lo.y), z: r2(b.hi.z - b.lo.z) },
556	  nonzeroThickness: (b.hi.x - b.lo.x) > 0 && (b.hi.y - b.lo.y) > 0 && (b.hi.z - b.lo.z) > 0,
557	  topAtOrBelowCap: b.name === 'backing' ? null : b.name === 'cap' ? b.hi.y <= headCapTopY : b.hi.y <= solidCapY + 1e-9
558	});
559	const overlapVolume = (a: Box, b: Box) => {
560	  const d = (ax: 'x' | 'y' | 'z') => Math.min(a.hi[ax], b.hi[ax]) - Math.max(a.lo[ax], b.lo[ax]);
561	  return { x: r2(d('x')), y: r2(d('y')), z: r2(d('z')), connected: d('x') > 0 && d('y') > 0 && d('z') > 0 };
562	};
563	
564	// --- apparatus footing over the FULL solid footprint (backing+stand+bracket)
565	let footing = true;
566	const footLo = { x: Math.min(...SOLIDS.map(b => b.lo.x)), z: Math.min(...SOLIDS.map(b => b.lo.z)) };
567	const footHi = { x: Math.max(...SOLIDS.map(b => b.hi.x)), z: Math.max(...SOLIDS.map(b => b.hi.z)) };
568	const footingColumns: Array<[number, number, number | null]> = [];
569	for (let u = Math.round((footLo.x - 1) / VOXEL_SCALE); u <= Math.round((footHi.x + 1) / VOXEL_SCALE); u++) {
570	  for (let v = Math.round((footLo.z - 1) / VOXEL_SCALE); v <= Math.round((footHi.z + 1) / VOXEL_SCALE); v++) {
571	    const cx = u * VOXEL_SCALE, cz = v * VOXEL_SCALE;
572	    if (cx + 1 < footLo.x || cx - 1 > footHi.x || cz + 1 < footLo.z || cz - 1 > footHi.z) continue;
573	    const nc = cellAt(u, v);
574	    footingColumns.push([u, v, nc ? nc.h : null]);
575	    if (!nc || Math.abs(nc.h - Rp.cell.h) > 0) footing = false;
576	  }
577	}
578	note(footing, 'apparatus footprint (backing+stand+bracket+cap) not on uniform supported dry ground');
579	
580	// --- walk mask includes ALL solids, inflated by the body radius only -------
581	const footprints = SOLIDS.map(b => ({
582	  name: b.name,
583	  lo: { x: b.lo.x - BODY_RADIUS, z: b.lo.z - BODY_RADIUS },
584	  hi: { x: b.hi.x + BODY_RADIUS, z: b.hi.z + BODY_RADIUS }
585	}));
586	const allowed = new Uint8Array(nodes.length);
587	for (let i = 0; i < nodes.length; i++) {
588	  if (!trunkAllowed[i]) continue;
589	  const n = nodes[i].world;
590	  const blocked = footprints.some(f => n.x >= f.lo.x && n.x <= f.hi.x && n.z >= f.lo.z && n.z <= f.hi.z);
591	  allowed[i] = blocked ? 0 : 1;
592	}
593	const segBlocked = (pts: THREE.Vector3[]) => {
594	  const tb = trunkBox(BODY_RADIUS);
595	  for (let i = 1; i < pts.length; i++) {
596	    const a = new THREE.Vector3(pts[i - 1].x, 0, pts[i - 1].z);
597	    const b = new THREE.Vector3(pts[i].x, 0, pts[i].z);
598	    if (segmentHitsBox(a, b, { ...tb.lo, y: -1 }, { ...tb.hi, y: 1 })) return 'trunk';
599	    for (const f of footprints) {
600	      if (segmentHitsBox(a, b, { x: f.lo.x, y: -1, z: f.lo.z }, { x: f.hi.x, y: 1, z: f.hi.z })) return f.name;
601	    }
602	  }
603	  return null;
604	};
605	const idxOf = (p: Pose) => nodeIndex.get(`${p.cell.u},${p.cell.v}`)!;
606	const materialise = (path: number[], from: Pose, to: Pose) => {
607	  const pts: THREE.Vector3[] = [from.world.clone()];
608	  for (const i of path) if (pts[pts.length - 1].distanceTo(nodes[i].world) > 1e-6) pts.push(nodes[i].world.clone());
609	  if (pts[pts.length - 1].distanceTo(to.world) > 1e-6) pts.push(to.world.clone());
610	  const length = groundedSurfaceRouteLength(pts.map(position => ({ position })), UP);
611	  return { pts, length, samples: traceSamples(pts), dense: densePoints(pts) };
612	};
613	const sup = (ground: THREE.Vector3, actorH: number) => supportPoint(ground, actorH, refSocket, Rp.world, RANGE, SOLIDS);
614	
615	// --- fixed-valid endpoints -------------------------------------------------
616	const sS = sup(poses.S!.world, WORKER_SOCKET);
617	const sE = sup(poses.E!.world, WORKER_SOCKET);
618	note(sS.supported && sE.supported, 'S/E not fixed-valid against the actual 1.30 socket');
619	
620	// --- coverage mask ---------------------------------------------------------
621	const cov = new Uint8Array(nodes.length);
622	for (let i = 0; i < nodes.length; i++) {
623	  if (!allowed[i]) continue;
