625	  if (sup(nodes[i].world, WORKER_SOCKET).supported) cov[i] = 1;
626	}
627	
628	// --- SHORT route -----------------------------------------------------------
629	const shortPath = leastSupportedShortestPath(idxOf(poses.S!), idxOf(poses.E!), allowed, cov);
630	note(!!shortPath, 'no short route with all solids in the mask');
631	const shortM = materialise(shortPath!, poses.S!, poses.E!);
632	const shortCaps = {
633	  walkedUnits: r2(shortM.length), lengthCap: MAX_TRACE_LENGTH, withinLengthCap: shortM.length <= MAX_TRACE_LENGTH,
634	  sampleCount: shortM.samples.length, pointCap: MAX_TRACE_POINTS, withinPointCap: shortM.samples.length <= MAX_TRACE_POINTS,
635	  segmentIntersectsSolidOrTrunk: segBlocked(shortM.pts)
