640	const spanPoints = shortM.samples.slice(run.startIdx, run.endIdx + 1);
641	const spanReasons = Array.from(new Set(shortSup.slice(run.startIdx, run.endIdx + 1).map(s => s.blockedBy)));
642	note(run.walked >= MIN_UNSUPPORTED_SPAN, `unsupported short span ${r2(run.walked)} < ${MIN_UNSUPPORTED_SPAN}`);
643	note(spanReasons.length === 1 && spanReasons[0] === 'backing', `unsupported span not caused solely by the backing: ${spanReasons.join(',')}`);
644	
645	// --- LONG route ------------------------------------------------------------
646	const covAllowed = new Uint8Array(nodes.length);
