655	  lengthRatio: +(longM.length / shortM.length).toFixed(3),
656	  minExtraUnitsRequired: MIN_EXTRA_UNITS, minLengthRatioRequired: MIN_LENGTH_RATIO,
657	  sampleCount: longM.samples.length, withinPointCap: longM.samples.length <= MAX_TRACE_POINTS,
658	  withinLengthCap: longM.length <= MAX_TRACE_LENGTH,
659	  segmentIntersectsSolidOrTrunk: segBlocked(longM.pts),
660	  everySampleSupported: longSup.every(s => s.supported),
661	  everyDensePointSupported: longDenseSup.every(s => s.supported),
662	  denseSpacingUnits: SEGMENT_DENSE_SPACING, densePointCount: longM.dense.length,
663	  minRangeMarginUnits: r2(Math.min(...longDenseSup.map(s => RANGE - s.distance))),
664	  firstUnsupported: longDenseSup.findIndex(s => !s.supported)
