670	
671	// --- endpoint reference insufficiency --------------------------------------
672	const coversWholeSpan = (ground: THREE.Vector3, socketH: number) => {
673	  const s = new THREE.Vector3(ground.x, ground.y + socketH, ground.z);
674	  const per = spanPoints.map(p => supportPoint(p, WORKER_SOCKET, s, ground, RANGE, SOLIDS));
