678	const endpointS = coversWholeSpan(poses.S!.world, PLAYER_SOCKET);
679	const endpointE = coversWholeSpan(poses.E!.world, PLAYER_SOCKET);
680	note(!endpointS.covers && !endpointE.covers, 'an endpoint reference alone already witnesses the entire unsupported span');
681	
682	// --- SHIFTED intermediate witness W(-34,51.05,10) --------------------------
683	function witnessReport(p: Pose | null, label: string) {
684	  if (!p) return { label, valid: false, reason: 'does not ground' };
685	  const s = new THREE.Vector3(p.world.x, p.world.y + PLAYER_SOCKET, p.world.z);
686	  const per = spanPoints.map(q => supportPoint(q, WORKER_SOCKET, s, p.world, RANGE, SOLIDS));
687	  const clear = distanceToPolyline(p.world, shortM.pts);
688	  const reachable = !!bfsPath(idxOf(poses.S!), idxOf(p), allowed);
689	  return {
690	    label, position: v3(p.world), supportVoxel: [p.cell.u, p.cell.h, p.cell.v],
691	    socketWorld: v3(s), socketHeight: PLAYER_SOCKET, bodyHeight: PLAYER_BODY_HEIGHT,
692	    bodyDiscFullySupported: p.clear,
693	    coversWholeUnsupportedSpan: per.every(x => x.supported),
694	    coveredSpanSamples: per.filter(x => x.supported).length, spanSamples: per.length,
695	    firstFailure: per.find(x => !x.supported) ?? null,
696	    maxLineOfReferenceDistance: r2(Math.max(...per.map(x => x.distance))),
697	    rangeMarginUnits: r2(RANGE - Math.max(...per.map(x => x.distance))),
698	    bodyClearanceFromSurveyRoute: r2(clear),
699	    meetsBodyBodyClearance: clear >= BODY_BODY_CLEARANCE, bodyBodyClearanceRequired: BODY_BODY_CLEARANCE,
700	    occupancyCylinderMarginUnits: r2(clear - OCCUPY_R),
701	    releaseCylinderMarginUnits: r2(clear - RELEASE_R),
702	    releaseCylinderOverlapsRoute: clear < RELEASE_R,
703	    reachableOnFootFromS: reachable,
704	    insideAnySolidFootprint: footprints.some(f => p.world.x >= f.lo.x && p.world.x <= f.hi.x && p.world.z >= f.lo.z && p.world.z <= f.hi.z),
705	    valid: p.clear && per.every(x => x.supported) && clear >= BODY_BODY_CLEARANCE && reachable
706	  };
707	}
708	const wShift = witnessReport(poses.W, 'W shifted (-34,51.05,10)');
709	const wNominal = witnessReport(poses.WNominal, 'W nominal (-34,51.05,11)');
710	note((wShift as any).valid === true, 'shifted intermediate witness W(-34,51.05,10) is INVALID');
711	
712	// --- E -> C common passage; held worker reference at E ----------------------
713	const ecPath = bfsPath(idxOf(poses.E!), idxOf(poses.C!), allowed);
714	note(!!ecPath, 'no E->C route with all solids in the mask');
715	const ecM = materialise(ecPath!, poses.E!, poses.C!);
716	const heldE = new THREE.Vector3(poses.E!.world.x, poses.E!.world.y + WORKER_SOCKET, poses.E!.world.z);
717	const heldSamples = ecM.samples.map(p => supportPoint(p, PLAYER_SOCKET, heldE, poses.E!.world, RANGE, SOLIDS));
718	const heldDense = ecM.dense.map(p => supportPoint(p, PLAYER_SOCKET, heldE, poses.E!.world, RANGE, SOLIDS));
719	const headSamples = ecM.samples.map(p => sup(p, PLAYER_SOCKET));
720	const ecReport = {
721	  walkedUnits: r2(ecM.length), sampleCount: ecM.samples.length, densePointCount: ecM.dense.length,
722	  withinLengthCap: ecM.length <= MAX_TRACE_LENGTH, withinPointCap: ecM.samples.length <= MAX_TRACE_POINTS,
723	  segmentIntersectsSolidOrTrunk: segBlocked(ecM.pts),
724	  vertices: ecM.pts.map(v3),
725	  heldReferenceAtE: { socketWorld: v3(heldE), socketHeight: WORKER_SOCKET, source: 'AuditWorker torso 1.30 + visor 0.55' },
726	  everySampleInRangeOfHeldE: heldSamples.every(s => s.inRange),
727	  everySampleUnobstructedFromHeldE: heldSamples.every(s => s.supported),
728	  everyDensePointInRangeOfHeldE: heldDense.every(s => s.inRange),
729	  everyDensePointUnobstructedFromHeldE: heldDense.every(s => s.supported),
730	  maxDistanceFromHeldE: r2(Math.max(...heldDense.map(s => s.distance))),
731	  minRangeMarginFromHeldE: r2(RANGE - Math.max(...heldDense.map(s => s.distance))),
732	  heldFailures: heldDense.map((s, i) => ({ i, p: v3(ecM.dense[i]), ...s })).filter(s => !s.supported).slice(0, 8),
733	  unitsOutsideFixedReference: r2(headSamples.reduce((acc, s, i) => acc + (i > 0 && !s.supported ? ecM.samples[i].distanceTo(ecM.samples[i - 1]) : 0), 0))
734	};
735	note(ecReport.withinLengthCap && ecReport.withinPointCap && ecReport.segmentIntersectsSolidOrTrunk === null, 'E->C route violates caps or hits a solid');
736	note(ecReport.everySampleInRangeOfHeldE && ecReport.everySampleUnobstructedFromHeldE, 'an E->C sample is out of range or obstructed from the held E reference');

