997	      contiguousSpanUnits: r2(commonRun.walked),
998	      spanStart: v3(ecM.samples[commonRun.s]), spanEnd: v3(ecM.samples[commonRun.e]),
999	      fractionOfPassage: +(commonRun.walked / ecM.length).toFixed(3), nonzero: commonRun.walked > 0
1000	    } : { contiguousSpanUnits: 0, nonzero: false }
1001	  },
