      const hazard = insideRendered && terrain.isHazardousVoxel!(u, y, v);
      if (terrain.isWaterVoxel(u, y, v)) wet = true;
      if (lift <= WORKER_ROUTE_OPTIONS.clearanceCells && (solid || hazard)) bodyBlocked = true;
