// --- line of sight (verbatim DDA + boxes) ----------------------------------
type Box = { lo: Record<'x' | 'y' | 'z', number>; hi: Record<'x' | 'y' | 'z', number> };
type NamedBox = Box & { name: string };
function segmentHitsBox(a: THREE.Vector3, b: THREE.Vector3, lo: Box['lo'], hi: Box['hi']): boolean {
