    const a = points[i - 1], b = points[i];
    const len = a.distanceTo(b);
    const n = Math.max(1, Math.ceil(len / SEGMENT_DENSE_SPACING));
    for (let s = 1; s <= n; s++) out.push(a.clone().lerp(b, s / n));
  }
  return out;
}

// --- node field (verbatim) -------------------------------------------------
const nodes: Cell[] = [];
const nodeIndex = new Map<string, number>();
