const longM = materialise(longPath!, poses.S!, poses.E!);
const longSup = longM.samples.map(p => sup(p, WORKER_SOCKET));
const longDenseSup = longM.dense.map(p => sup(p, WORKER_SOCKET));
const longCaps = {
