    const sSw = supportPoint(poses.S!.world, WORKER_SOCKET, wrong, Rp.world, RANGE, SOLIDS);
    const covWrong = shortM.samples.map(p => supportPoint(p, WORKER_SOCKET, wrong, Rp.world, RANGE, SOLIDS));
