    return { S_distance: sSw.distance, S_supported: sSw.supported, unsupportedShortSpanUnits: r2(runWrong.walked),
      differsFromMeasured: Math.abs(runWrong.walked - run.walked) > 1e-9 || sSw.distance !== sS.distance };
  })()
};

