const ecReport = {
  walkedUnits: r2(ecM.length), sampleCount: ecM.samples.length, densePointCount: ecM.dense.length,
  withinLengthCap: ecM.length <= MAX_TRACE_LENGTH, withinPointCap: ecM.samples.length <= MAX_TRACE_POINTS,
  segmentIntersectsSolidOrTrunk: segBlocked(ecM.pts),
  vertices: ecM.pts.map(v3),
  heldReferenceAtE: { socketWorld: v3(heldE), socketHeight: WORKER_SOCKET, source: 'AuditWorker torso 1.30 + visor 0.55' },
  everySampleInRangeOfHeldE: heldSamples.every(s => s.inRange),
  everySampleUnobstructedFromHeldE: heldSamples.every(s => s.supported),
  everyDensePointInRangeOfHeldE: heldDense.every(s => s.inRange),
  everyDensePointUnobstructedFromHeldE: heldDense.every(s => s.supported),
