    const vertOverlap = Math.min(bodyTop, b.hi.y) - Math.max(p.world.y, b.lo.y) > 0;
    return { solid: b.name, planarGapToSurface: r2(planar), capsuleIntersects: planar < BODY_RADIUS && vertOverlap };
  });
