// --- unchanged caps / thresholds (verbatim; none added, none relaxed) -------
const MAX_TRACE_POINTS = 128;
const MAX_TRACE_LENGTH = 120;
const SAMPLE_SPACING = 1.0;
const MIN_SAMPLE_SEPARATION = 0.25;
const MIN_EXTRA_UNITS = 12;
