function shippedColumnTop(vx: number, vz: number): number | null {
  for (let h = RADIUS_CELLS; h >= 0; h--) {
    if (!terrain.isSolidVoxel(vx, h, vz)) continue;
    if (h < RADIUS_CELLS && terrain.isSolidVoxel(vx, h + 1, vz)) continue;
