    let j = i;
    while (j + 1 < ecM.samples.length && !headSamples[j + 1].supported && heldSamples[j + 1].supported) j++;
    let walked = 0;
    for (let m = i + 1; m <= j; m++) walked += ecM.samples[m].distanceTo(ecM.samples[m - 1]);
