const CAP_LOCAL = { lo: { x: -0.20, y: SOLID_CAP_LOCAL_Y, z: -0.20 }, hi: { x: 0.20, y: HEAD_CAP_TOP_LOCAL_Y, z: 0.20 } };

const CANDIDATE = {
