    const dd = d[ax];
    if (dd === 0) { if (a[ax] < lo[ax] || a[ax] > hi[ax]) return null; continue; }
    let t1 = (lo[ax] - a[ax]) / dd;
    let t2 = (hi[ax] - a[ax]) / dd;
    if (t1 > t2) { const s = t1; t1 = t2; t2 = s; }
