  for (let v = Math.round((footLo.z - 1) / VOXEL_SCALE); v <= Math.round((footHi.z + 1) / VOXEL_SCALE); v++) {
    const cx = u * VOXEL_SCALE, cz = v * VOXEL_SCALE;
