    const a = pts[i - 1], b = pts[i];
    ab.subVectors(b, a); ap.subVectors(p, a);
    const denom = ab.lengthSq();
    const t = denom < 1e-9 ? 0 : Math.max(0, Math.min(1, ap.dot(ab) / denom));
    best = Math.min(best, p.distanceTo(a.clone().addScaledVector(ab, t)));
  }
