  const u = Math.round(x / VOXEL_SCALE), v = Math.round(z / VOXEL_SCALE);
  if (Math.max(Math.abs(u), Math.abs(v)) > MAX_TOPFACE_CELL) return null;
  const c = cellAt(u, v);
