  let i = 0;
  while (i < samples.length) {
    if (ok[i]) { i++; continue; }
    let j = i;
    while (j + 1 < samples.length && !ok[j + 1]) j++;
    let walked = 0;
    for (let k = i + 1; k <= j; k++) walked += samples[k].distanceTo(samples[k - 1]);
